-- 027_daily_affirmations.sql
-- 365 affirmations — une par jour (brief Shy « Module Mindset », v2.0, sept. 2026).
-- La phrase dépend de la date LOCALE de l'appareil (mois + jour), pas de la date
-- d'inscription : toutes les utilisatrices lisent la même phrase le même jour.
-- Le 29 février porte l'affirmation bonus ; les autres jours ne sont pas décalés.
-- Volontairement : aucun compteur, aucun historique, aucune donnée par utilisatrice.
-- Texte de référence = français (apostrophes ’ et guillemets « » conservés) ;
-- i18n.en.text = version anglaise. Les autres langues retombent sur le français.

create table if not exists public.daily_affirmations (
  month smallint not null check (month between 1 and 12),
  day smallint not null check (day between 1 and 31),
  text text not null,
  i18n jsonb default '{}'::jsonb,
  updated_at timestamptz default now(),
  primary key (month, day)
);

alter table public.daily_affirmations enable row level security;

drop policy if exists "daily_affirmations_read" on public.daily_affirmations;
create policy "daily_affirmations_read" on public.daily_affirmations
  for select to authenticated using (true);
drop policy if exists "daily_affirmations_admin_write" on public.daily_affirmations;
create policy "daily_affirmations_admin_write" on public.daily_affirmations
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

on conflict (month, day) do update
  set text = excluded.text, i18n = excluded.i18n, updated_at = now();
